2107:popover > arrow, popover > contents { background-color: var(--popover-bg-color); color: var(--popover-fg-color); background-clip: padding-box; border: 1px solid RGB(0 0 0/14%); box-shadow: 0 1px 5px 1px RGB(0 0 0/9%), 0 2px 14px 3px RGB(0 0 0/5%); }
2283:scrollbar > range > trough > slider { min-width: 8px; min-height: 8px; margin: -8px; border: 8px solid transparent; border-radius: 99px; background-clip: padding-box; transition: all 200ms linear; background-color: color-mix(in srgb, currentColor 20%, transparent); }
2916:tooltip.background { background-color: RGB(0 0 6/80%); background-clip: padding-box; border: 1px solid RGB(255 255 255/10%); color: white; }

